const escapeRe = (s: string) => s.replace(/[.*+?^${}()|[\]\\/]/g, "\\$&");
const isAscii = (s: string) => /^[\x00-\x7F]+$/.test(s);
const SORTED = [...ABILITY_PLAIN_MAP].sort((a, b) => b.official.length - a.official.length);

/**
 * Resmi yetenek adlarını düz Silver-koç terimine çevirir (dil-duyarlı).
 * Apostrof-eki yutar: İngilizce-jargon terimde korur (smoke'u/flash'ı doğru),
 * Türkçe terimde düşürür (Slow Orb'u → "yavaşlatma", "yavaşlatma'u" değil).
 */
export function plainifyAbilities(text: string, lang: "tr" | "en"): string {
  let outText = text;
  for (const e of SORTED) {
    const term = lang === "tr" ? e.tr : e.en;
    // Unicode-aware letter boundary (\p{L} + 'u' flag): JS \b breaks on Turkish
    // letters, so an APOSTROPHELESS bitişik ek ("Boltu", "Boltuyla") slipped past
    // the old \b boundary and leaked the codename. The suffix group's apostrophe
    // is now OPTIONAL so the contiguous ek is captured too. isAscii(term) ⇒ keep
    // term+suf (English jargon "recon" stays "recon"); else drop the ek and let
    // fixTurkishApostrophe re-attach the correct Turkish suffix.
    const re = new RegExp("(?<![\\p{L}])" + escapeRe(e.official) + "(['’]?[a-zçğıöşü]+)?(?![\\p{L}])", "giu");
    outText = outText.replace(re, (_m: string, suf?: string) => (suf && isAscii(term)) ? term + suf : term);
  }
  return outText;
}

// ─── Türkçe düz-terim apostrof düzeltici ──────────────────────────────────
// Model bazen düz Türkçe terimi yanlış apostroflar ("duvar'i", "tuzak'ı", "tel'i").
// Türkçe ortak isimler apostrof almaz — doğru eki (ünlü uyumu + ünsüz yumuşaması) getir.
const TR_TERMS = ["yavaşlatma", "sersemletme", "sabitleme", "diriltme", "çekme", "zıplama", "kalkan", "kamera", "tuzak", "bıçak", "kaçış", "duvar", "diken", "siper", "açı", "tel"];
const VOWELS = "aeıioöuü";
const lastVowel = (w: string) => { for (let i = w.length - 1; i >= 0; i--) if (VOWELS.includes(w[i])) return w[i]; return "a"; };
const highV = (lv: string) => (({ a: "ı", "ı": "ı", o: "u", u: "u", e: "i", i: "i", "ö": "ü", "ü": "ü" } as Record<string, string>)[lv] ?? "ı");
const lowV = (lv: string) => ("aıou".includes(lv) ? "a" : "e");
const soften = (stem: string) => { const c = stem[stem.length - 1]; const m = ({ k: "ğ", p: "b", "ç": "c", t: "d" } as Record<string, string>)[c]; return m ? stem.slice(0, -1) + m : stem; };
const voicelessEnd = (stem: string) => "fstkçşhp".includes(stem[stem.length - 1]);
const cap = (orig: string, w: string) => (orig[0] === orig[0].toUpperCase() ? w[0].toUpperCase() + w.slice(1) : w);

export function fixTurkishApostrophe(text: string): string {
  let out = text;
  for (const term of TR_TERMS) {
    const re = new RegExp("\\b(" + term + ")(['’])([a-zçğıöşü]+)", "gi");
    out = out.replace(re, (_m, t: string, _ap: string, suf: string) => {
      const stem = t.toLowerCase();
      const lv = lastVowel(stem);
      const vEnd = VOWELS.includes(stem[stem.length - 1]);
      const s = suf.toLowerCase();
      let res: string;
      if (/^(dan|den|tan|ten)$/.test(s)) res = stem + (voicelessEnd(stem) ? "t" : "d") + lowV(lv) + "n";        // ablatif
      else if (/^(da|de|ta|te)$/.test(s)) res = stem + (voicelessEnd(stem) ? "t" : "d") + lowV(lv);              // bulunma
      else if (/^[ıiuü]n$/.test(s)) res = soften(stem) + (vEnd ? "n" : "") + highV(lv) + "n";                    // tamlayan
      else if (/^[ae]$/.test(s)) res = soften(stem) + (vEnd ? "y" : "") + lowV(lv);                              // yönelme
      else if (/^[ıiuü]$/.test(s)) res = soften(stem) + (vEnd ? "y" : "") + highV(lv);                           // belirtme
      else res = stem + suf;                                                                                      // bilinmeyen: apostrofu at
      return cap(t, res);
    });
  }
  return out;
}
